"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { AspectRatio } from "@/components/ui/aspect-ratio"
import { Meta } from "@/components/ui/meta"

type FigureProps = Omit<React.ComponentProps<"figure">, "children"> & {
  src: string
  /** What the picture shows. Read aloud, and set in the frame in its place if the picture can't be loaded. */
  alt: string
  srcSet?: string
  sizes?: string
  /** Width over height of the crop. 3 / 2 by default, the 35mm negative. Change it and the picture recrops as the frame eases. */
  ratio?: number
  /** Where the crop holds the picture, as CSS object-position. */
  position?: string
  /** The figure's number, set as data before the caption: 01. */
  number?: React.ReactNode
  caption?: React.ReactNode
  /** Who made it, spread to the far end of the caption row. */
  credit?: React.ReactNode
  /** plate: the caption under the picture. margin: the caption in the margin beside it, the number at its head. */
  variant?: "plate" | "margin"
  loading?: "lazy" | "eager"
}

/** A picture cropped to a ratio and marked like a printer's proof, with its number, caption and credit set as type. */
function Figure({ src, alt, srcSet, sizes, ratio = 3 / 2, position, number, caption, credit, variant = "plate", loading = "lazy", className, ...props }: FigureProps) {
  const img = React.useRef<HTMLImageElement>(null)
  // A picture that failed before hydration fires no error event we can hear: look once it's mounted.
  React.useEffect(() => {
    const el = img.current
    if (el) el.closest("figure")?.toggleAttribute("data-missing", el.complete && el.naturalWidth === 0)
  }, [src])
  const mark = (on: boolean) => (e: React.SyntheticEvent<HTMLImageElement>) => e.currentTarget.closest("figure")?.toggleAttribute("data-missing", on)

  return (
    <figure data-slot="figure" data-variant={variant} className={cn("db-figure", className)} {...props}>
      <AspectRatio ratio={ratio} className="db-figure-frame">
        {/* eslint-disable-next-line @next/next/no-img-element -- a registry item is framework-agnostic */}
        <img
          ref={img}
          src={src}
          srcSet={srcSet}
          sizes={sizes}
          alt={alt}
          loading={loading}
          decoding="async"
          className="db-figure-img"
          style={position ? { objectPosition: position } : undefined}
          onLoad={mark(false)}
          onError={mark(true)}
        />
        {alt ? (
          <span className="db-figure-alt" aria-hidden="true">
            {alt}
          </span>
        ) : null}
      </AspectRatio>
      {number != null || caption || credit ? (
        <figcaption className="db-figure-caption">
          {number != null ? (
            <span className="db-figure-number">
              <span className="db-sr">Figure </span>
              {number}
            </span>
          ) : null}
          <Meta className="db-figure-lines">
            {caption ? <span className="db-figure-text">{caption}</span> : null}
            {credit ? <span className="db-figure-credit">{credit}</span> : null}
          </Meta>
        </figcaption>
      ) : null}
    </figure>
  )
}

export { Figure, type FigureProps }

@layer components {
  /* ── db-figure ── a picture cropped to a ratio and marked like a printer's proof (the aspect ratio's trim marks), then named in
     type: its number as data, the caption in the voice, the credit spread to the far end on the same baseline, as "the silence
     that heals" sets its camera and its archive under the picture. No filter, no mask, no zoom: the picture is shown as it is. */
  .db-figure { display: grid; gap: var(--db-space-6); margin: 0; min-width: 0; container-type: inline-size; }
  .db-figure-frame { width: 100%; overflow: visible; }
  .db-figure-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: 50% 50%; }
  /* The picture that isn't there is described in its place, inside the marks, the way a layout holds a place for one. */
  .db-figure-alt { display: none; max-width: 30ch; padding: var(--db-space-4); text-align: center; font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); }
  .db-figure[data-missing] .db-figure-img { opacity: 0; }
  .db-figure[data-missing] .db-figure-alt { display: block; }

  .db-figure-caption { display: flex; align-items: first baseline; gap: var(--db-space-4); min-width: 0; }
  .db-figure-number { flex: none; font-size: var(--db-mp); line-height: 1; font-weight: 300; letter-spacing: var(--db-mp-tr); font-variant-numeric: tabular-nums lining-nums; color: var(--db-ink); }
  .db-figure-lines { flex: 1; min-width: 0; }
  .db-figure-text { max-width: 44ch; text-wrap: pretty; }
  .db-figure-credit { max-width: 24ch; color: var(--db-pencil); text-align: end; }
  /* Narrow: no room to spread the credit to the far end, so it steps under the caption and the hairline goes. */
  @container (width < 26rem) {
    .db-figure-lines { flex-direction: column; align-items: start; gap: var(--db-space-1); }
    .db-figure-lines > hr { display: none; }
    .db-figure-credit { text-align: start; }
  }

  /* margin: the caption stands in the margin beside the picture, as a book sets a side caption in the columns kept for notes (3 of 12):
     the number at the head, level with the picture's top, the caption and credit at the foot, level with its foot.
     Where the two can't stand side by side the caption falls under the picture. */
  .db-figure[data-variant="margin"] { display: flex; flex-flow: row-reverse wrap; gap: var(--db-space-5) var(--db-space-6); }
  .db-figure[data-variant="margin"] > .db-figure-frame { flex: 9 1 0; min-width: min(100%, 20rem); }
  .db-figure[data-variant="margin"] > .db-figure-caption { flex: 3 1 0; min-width: 9rem; flex-direction: column; justify-content: space-between; align-items: stretch; gap: var(--db-space-4); }
  .db-figure[data-variant="margin"] .db-figure-number { font-size: var(--db-mf); letter-spacing: var(--db-mf-tr); font-weight: 200; }
  .db-figure[data-variant="margin"] .db-figure-lines { flex: none; flex-direction: column; align-items: start; gap: var(--db-space-2); }
  .db-figure[data-variant="margin"] .db-figure-lines > hr { display: none; }
  .db-figure[data-variant="margin"] .db-figure-credit { text-align: start; }
}
